import{_ as n}from"./chunks/einstellungen-globale-einstellungen-1-allgemein-einstellungen.D7Llh1te.js";import{_ as r,o as t,c as s,a3 as l}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/schueler/werkzeuge-fotos-skalieren.png",m=JSON.parse('{"title":"Gespeicherte Schülerfotos neu skalieren","description":"","frontmatter":{"title":"Gespeicherte Schülerfotos neu skalieren","source_pageid":743,"source_revision":5285},"headers":[],"relativePath":"schild3/schueler/fotos-neu-skalieren-verwaltung-werkzeuge.md","filePath":"schild3/schueler/fotos-neu-skalieren-verwaltung-werkzeuge.md"}'),a={name:"schild3/schueler/fotos-neu-skalieren-verwaltung-werkzeuge.md"};function o(u,e,g,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="gespeicherte-schulerfotos-neu-skalieren" tabindex="-1">Gespeicherte Schülerfotos neu skalieren <a class="header-anchor" href="#gespeicherte-schulerfotos-neu-skalieren" aria-label="Permalink to &quot;Gespeicherte Schülerfotos neu skalieren&quot;">​</a></h1><p>Passen Sie vorhandene Schülerfotos an die in den globalen Einstellungen festgelegte maximale Bildgröße an.</p><p><a href="/bilder/schueler/werkzeuge-fotos-skalieren.png"><img src="'+i+'" alt="Fotos neu skalieren." loading="lazy"></a></p><p><em>Fotos neu skalieren.</em></p><p>SchILD speichert Fotos standardmäßig mit einer maximalen Breite oder Höhe von 160 Pixeln. Dadurch bleibt die Datenbank kleiner. Die maximale Bildgröße können Sie in den Einstellungen ändern.</p><p>Die Einstellung für die Größe der Bilder/Fotos findet sich unter <em>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen ➜ Allgemeines ➜ Sonstiges ➜ Fotos Skalieren auf</em>. Dort kann der gewünschte Wert gesetzt werden.</p><p>Um bereits gespeicherte Fotos an die eingestellte Größe anzupassen, wählen Sie <strong>Verwaltung ➜ Werkzeuge ➜ Fotos neu skalieren</strong>.</p><p><a href="/bilder/benutzer-einstellungen/einstellungen-globale-einstellungen-1-allgemein-einstellungen.png"><img src="'+n+'" alt="Setzen der gewünschten Größe von Fotos in den Einstellungen." loading="lazy"></a></p><p><em>Setzen der gewünschten Größe von Fotos in den Einstellungen.</em></p><p>Anpassen der Standardgröße für Fotos in den Einstellungen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fotos_neu_skalieren_(Verwaltung_Werkzeuge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5285.</p>',12)])])}const f=r(a,[["render",o]]);export{m as __pageData,f as default};
